package configuration

import (
	"fmt"
	"strconv"
)

// Source resolves a configuration key to a raw value.
type Source func(key string) (value string, found bool)

// Config holds the application configuration.
type Config struct {
	Port  int
	Name  string
	Debug bool
}

// Load reads configuration from source.
func Load(source Source) (Config, error) {
	cfg := Config{
		Port:  8080,
		Name:  "helios",
		Debug: false,
	}

	if v, ok := source("HELIOS_PORT"); ok {
		port, err := strconv.Atoi(v)
		if err != nil {
			return Config{}, fmt.Errorf("configuration: %w", err)
		}
		if port < 1 || port > 65535 {
			return Config{}, fmt.Errorf("configuration: port %d out of range (1-65535)", port)
		}
		cfg.Port = port
	}

	if v, ok := source("HELIOS_NAME"); ok {
		if v == "" {
			return Config{}, fmt.Errorf("configuration: HELIOS_NAME must not be empty")
		}
		cfg.Name = v
	}

	if v, ok := source("HELIOS_DEBUG"); ok {
		debug, err := strconv.ParseBool(v)
		if err != nil {
			return Config{}, fmt.Errorf("configuration: %w", err)
		}
		cfg.Debug = debug
	}

	return cfg, nil
}

package main

import (
	"fmt"
	"os"

	"example.helios/configuration"
)

func main() {
	cfg, err := configuration.Load(func(key string) (string, bool) {
		return os.LookupEnv(key)
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("port=%d name=%s debug=%t\n", cfg.Port, cfg.Name, cfg.Debug)
}

package configuration

import (
	"errors"
	"strconv"
	"testing"
)

func staticSource(m map[string]string) Source {
	return func(key string) (string, bool) {
		v, ok := m[key]
		return v, ok
	}
}

func TestLoadDefaults(t *testing.T) {
	cfg, err := Load(staticSource(nil))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want \"helios\"", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

func TestLoadPort(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  int
	}{
		{"valid min", "1", 1},
		{"valid max", "65535", 65535},
		{"valid typical", "3000", 3000},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cfg, err := Load(staticSource(map[string]string{"HELIOS_PORT": tt.input}))
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if cfg.Port != tt.want {
				t.Errorf("Port = %d, want %d", cfg.Port, tt.want)
			}
		})
	}
}

func TestLoadPortError(t *testing.T) {
	tests := []struct {
		name  string
		input string
	}{
		{"not a number", "abc"},
		{"zero", "0"},
		{"negative", "-1"},
		{"overflow", "65536"},
		{"overflow huge", "99999"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := Load(staticSource(map[string]string{"HELIOS_PORT": tt.input}))
			if err == nil {
				t.Fatal("expected error, got nil")
			}
		})
	}
}

func TestLoadPortPreservesParseError(t *testing.T) {
	_, err := Load(staticSource(map[string]string{"HELIOS_PORT": "abc"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if !errors.As(err, &strconv.NumError{}) {
		// errors.As on a struct value won't work — use pointer type
		var numErr *strconv.NumError
		if !errors.As(err, &numErr) {
			t.Errorf("error does not wrap *strconv.NumError: %v", err)
		}
	}
}

func TestLoadName(t *testing.T) {
	cfg, err := Load(staticSource(map[string]string{"HELIOS_NAME": "my-server"}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Name != "my-server" {
		t.Errorf("Name = %q, want \"my-server\"", cfg.Name)
	}
}

func TestLoadNameEmpty(t *testing.T) {
	_, err := Load(staticSource(map[string]string{"HELIOS_NAME": ""}))
	if err == nil {
		t.Fatal("expected error for empty name, got nil")
	}
}

func TestLoadDebug(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  bool
	}{
		{"true", "true", true},
		{"false", "false", false},
		{"1", "1", true},
		{"0", "0", false},
		{"T", "T", true},
		{"F", "F", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cfg, err := Load(staticSource(map[string]string{"HELIOS_DEBUG": tt.input}))
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if cfg.Debug != tt.want {
				t.Errorf("Debug = %t, want %t", cfg.Debug, tt.want)
			}
		})
	}
}

func TestLoadDebugError(t *testing.T) {
	_, err := Load(staticSource(map[string]string{"HELIOS_DEBUG": "notabool"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
}

func TestLoadDebugPreservesParseError(t *testing.T) {
	_, err := Load(staticSource(map[string]string{"HELIOS_DEBUG": "bogus"}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	var numErr *strconv.NumError
	if !errors.As(err, &numErr) {
		t.Errorf("error does not wrap *strconv.NumError: %v", err)
	}
}

func TestLoadPartialConfig(t *testing.T) {
	cfg, err := Load(staticSource(map[string]string{"HELIOS_PORT": "9090"}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 9090 {
		t.Errorf("Port = %d, want 9090", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want \"helios\"", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

